.process-flow {
  display: flex;
  flex-direction: column;
  overflow: hidden;
  box-sizing: border-box;
  color: var(--flow-fg, #242424);
  background: var(--flow-bg, #fff);
  font-family: "Segoe UI", Arial, sans-serif;
  font-size: 13px;
}
.process-flow .process-flow-summary,
.process-flow .process-flow-warning {
  flex: 0 0 auto;
  padding: 6px 10px;
  overflow-wrap: anywhere;
}
.process-flow .process-flow-summary {
  font-weight: 600;
}
.process-flow .process-flow-warning {
  border-left: 3px solid var(--flow-fg);
}
.process-flow .process-flow-state {
  padding: 12px 20px;
  overflow: auto;
}
.process-flow .process-flow-state h2 {
  margin: 0 0 10px;
  font-size: 18px;
}
.process-flow .process-flow-state p {
  max-width: 600px;
  line-height: 1.5;
}
.process-flow .process-flow-viewport {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
}
.process-flow .process-flow-graph {
  display: block;
}
.process-flow .process-flow-zoom {
  display: flex;
  flex: 0 0 42px;
  align-items: center;
  gap: 4px;
  padding: 0 8px;
  box-sizing: border-box;
  border-top: 1px solid var(--flow-fg);
  background: var(--flow-bg);
}
.process-flow .process-flow-zoom button {
  min-width: 30px;
  height: 28px;
  border: 1px solid var(--flow-fg);
  border-radius: 4px;
  color: inherit;
  background: var(--flow-bg);
  font: inherit;
  cursor: pointer;
}
.process-flow .process-flow-zoom button:hover {
  outline: 1px solid var(--flow-active);
}
.process-flow .process-flow-zoom button:focus-visible {
  outline: 2px solid var(--flow-active);
  outline-offset: 1px;
}
.process-flow .process-flow-zoom button:disabled {
  opacity: 0.4;
  cursor: default;
}
.process-flow .process-flow-zoom button[aria-pressed="true"] {
  border: 2px solid var(--flow-active);
}
.process-flow .process-flow-zoom-percentage {
  min-width: 48px;
  text-align: center;
  font-variant-numeric: tabular-nums;
}
.process-flow .process-flow-node-title {
  fill: var(--flow-fg);
  font-size: var(--flow-title-font-size);
  font-weight: 600;
}
.process-flow .process-flow-node-id {
  fill: var(--flow-fg);
  font-size: var(--flow-small-font-size);
}
.process-flow .process-flow-value {
  fill: var(--flow-fg);
  font-size: var(--flow-font-size);
  font-weight: 600;
}
.process-flow .process-flow-label {
  fill: var(--flow-fg);
  font-size: var(--flow-small-font-size);
}
